'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const n = nextInt();
const graph = Array.from({ length: n + 1 }, () => []);

for (let i = 1; i <= n; i++) {
  const m = nextInt();
  for (let j = 0; j < m; j++) {
    const x = nextInt();
    graph[i].push(x);
    graph[x].push(i);
  }
}

const color = new Int8Array(n + 1);
color.fill(-1);

for (let start = 1; start <= n; start++) {
  if (color[start] !== -1) continue;

  color[start] = start === 1 ? 0 : 0;
  const queue = [start];

  for (let head = 0; head < queue.length; head++) {
    const u = queue[head];
    for (const v of graph[u]) {
      if (color[v] === -1) {
        color[v] = color[u] ^ 1;
        queue.push(v);
      }
    }
  }
}

const team1 = [];
const team2 = [];
for (let i = 1; i <= n; i++) {
  (color[i] === 0 ? team1 : team2).push(i);
}

process.stdout.write(team1.join(' ') + '\n' + team2.join(' ') + '\n');
